        addRole("Pilot/PIC", otherEvent?.pilot);
        addRole("Instructor", event.instructor);
        addRole("Instructor", otherEvent?.instructor);
        addRole("Pilot 2 / WSO / Crew", event.crew);
        addRole("Pilot 2 / WSO / Crew", otherEvent?.crew);
